import{_ as r,o as s,c as t,a6 as o}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"边缘渲染 · 把服务端搬到离用户最近的地方","description":"传统 SSR 跑在一台（或一处）中心服务器上，离用户远、延迟高。边缘渲染把 SSR 搬到遍布全球的 CDN 边缘节点上运行，离用户只有几十毫秒。但边缘运行时受限、且「离用户近」往往意味着「离数据库远」——这是它最核心的取舍。","frontmatter":{"title":"边缘渲染 · 把服务端搬到离用户最近的地方","description":"传统 SSR 跑在一台（或一处）中心服务器上，离用户远、延迟高。边缘渲染把 SSR 搬到遍布全球的 CDN 边缘节点上运行，离用户只有几十毫秒。但边缘运行时受限、且「离用户近」往往意味着「离数据库远」——这是它最核心的取舍。","source":"https://daiw.org/manual/ssr/edge-rendering"},"headers":[],"relativePath":"manual/computer-programming/ssr/edge-rendering.md","filePath":"manual/computer-programming/ssr/edge-rendering.md"}'),n={name:"manual/computer-programming/ssr/edge-rendering.md"};function a(l,e,i,g,p,d){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="边缘渲染-·-把服务端搬到离用户最近的地方" tabindex="-1">边缘渲染 · 把服务端搬到离用户最近的地方 <a class="header-anchor" href="#边缘渲染-·-把服务端搬到离用户最近的地方" aria-label="Permalink to &quot;边缘渲染 · 把服务端搬到离用户最近的地方&quot;">​</a></h1><p>传统 SSR 跑在一台（或一处）中心服务器上，离用户远、延迟高。边缘渲染把 SSR 搬到遍布全球的 CDN 边缘节点上运行，离用户只有几十毫秒。但边缘运行时受限、且「离用户近」往往意味着「离数据库远」——这是它最核心的取舍。</p><p>前两章让 SSR 在「<strong>什么时候发</strong>」（流式）和「<strong>发多少 JS</strong>」（服务端组件）上变聪明了。这一章换个维度：<strong>在哪里渲染。</strong></p><p>传统 SSR 跑在一台中心服务器上（比如某个机房）。一个巴西用户访问部署在美国东部的站点，每个请求光是<strong>网络往返</strong>就要一两百毫秒——SSR 渲染得再快，也架不住物理距离。<strong>边缘渲染(edge rendering)</strong> 的答案是：把渲染代码<strong>部署到遍布全球的 CDN 边缘节点</strong>上，让它在<strong>离用户最近的那个节点</strong>执行。</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  U[&quot;巴西用户&quot;] --&gt;|&quot;~180ms 往返&quot;| O[&quot;美东中心服务器&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  U2[&quot;巴西用户&quot;] --&gt;|&quot;~20ms 往返&quot;| E[&quot;圣保罗边缘节点&lt;br/&gt;(就地 SSR)&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>同样一段 SSR 代码，从「一处运行、全球来访」变成「就近运行」，延迟直接砍掉一大截。</p><h2 id="边缘平台与「受限的运行时」" tabindex="-1">边缘平台与「受限的运行时」 <a class="header-anchor" href="#边缘平台与「受限的运行时」" aria-label="Permalink to &quot;边缘平台与「受限的运行时」&quot;">​</a></h2><p>跑边缘渲染的平台有 Cloudflare Workers、Vercel Edge Functions、Deno Deploy、Netlify Edge 等。它们靠的多是 <strong>V8 isolate</strong>（轻量隔离，而非每请求起一个完整容器），所以<strong>冷启动极快、能瞬间弹到全球</strong>。</p><p>但天下没有免费的午餐——<strong>边缘运行时是「阉割版」的</strong>：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>边缘不是完整的 Node.js。常见限制：<strong>没有完整的 Node API</strong>（文件系统、部分原生模块用不了，只有 <code>nodejs_compat</code> 之类的兼容层能补一部分）；<strong>CPU 时间有限</strong>（单请求几十毫秒量级，跑不了重计算）；<strong>包体积有上限</strong>；<strong>没有长驻进程 / 常驻连接</strong>。所以「把现有 Node SSR 原样搬上边缘」经常行不通，得挑选依赖、避开重活。<strong>边缘适合「轻量渲染」，不适合「在请求里跑一大坨 CPU 密集或依赖 Node 原生能力的活」。</strong></p></div><h2 id="最核心的取舍-离用户近-离数据库远" tabindex="-1">最核心的取舍：离用户近 = 离数据库远 <a class="header-anchor" href="#最核心的取舍-离用户近-离数据库远" aria-label="Permalink to &quot;最核心的取舍：离用户近 = 离数据库远&quot;">​</a></h2><p>边缘渲染有个绕不开、也最容易被忽略的坑：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>你把渲染搬到了离用户最近的地方，但你的数据库，通常还在某一处中心机房。</strong></p><p>于是尴尬的一幕出现了：边缘节点在圣保罗，离用户 20ms；可它要渲染页面得查数据，而数据库在美东——边缘节点<strong>回头去查那个远端数据库</strong>，又是 180ms。你在网络这头省下的，在数据那头又还回去了，甚至更糟（因为一个页面可能查好几次库）。这叫<strong>数据局部性(data locality)问题</strong>。</p></div><p>破解它有几条路：</p><ul><li><strong>让数据也「上边缘」</strong>：用边缘分布式存储——Cloudflare KV / D1 / R2、边缘 Redis、全球复制的数据库（如 Turso、PlanetScale 的边缘读），让边缘节点就近读到数据。</li><li><strong>让边缘只读缓存</strong>：边缘节点不直接查库，而是读<strong>就近的缓存</strong>（下一站的主题）——命中缓存就是本地读取，~0 延迟。这也是为什么<strong>边缘渲染和缓存是天生一对</strong>。</li><li><strong>分工</strong>：强数据依赖、重计算的页面留在中心服务器(origin)SSR；轻量、数据可缓存的页面上边缘。同一个站点混着来。</li></ul><h2 id="为什么边缘和缓存是一对" tabindex="-1">为什么边缘和缓存是一对 <a class="header-anchor" href="#为什么边缘和缓存是一对" aria-label="Permalink to &quot;为什么边缘和缓存是一对&quot;">​</a></h2><p>这一点值得单独点破，它是通往下一站的桥：<strong>CDN 的边缘节点，本来就是缓存住的地方。</strong> 当你的渲染逻辑也运行在边缘，它就能以<strong>近乎零延迟</strong>读取同一节点上的缓存数据、甚至直接命中缓存好的整页 HTML——不必回中心、不必查远端库。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>换句话说：<strong>边缘渲染真正发力，靠的往往不是「在边缘现算」，而是「在边缘命中缓存」。</strong> 一个理想的边缘页面：大部分请求直接吃边缘缓存（极快），只有缓存未命中时才就近渲染一次、并把结果缓存回边缘。渲染在边缘、缓存在边缘、数据尽量在边缘——三者合一，才是边缘渲染的完全体。这就自然把我们带到了整个专栏的重点。</p></div><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>边缘渲染把 SSR 搬到离用户最近的节点，大幅降低网络延迟；代价是运行时受限，以及那个核心取舍——<strong>离用户近往往离数据库远（数据局部性问题）</strong>。它的完全体，离不开「在边缘命中缓存」。</p><p>到这里，「更聪明地渲染」三招（流式、服务端组件、边缘）讲完了。它们都在缓解 SSR 的性能短板，但都没触及那个最根本的事实：<strong>SSR 每次请求都要现算，不缓存就扛不住。</strong> 从下一章起，我们进入本专栏的重点——<strong>缓存</strong>，先回答那个最本质的问题：为什么 SSR 一定要缓存？👉 <a href="/Front2Full/manual/computer-programming/ssr/why-cache">为什么 SSR 必须缓存</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Cloudflare.「What is edge computing? / Workers.」<a href="https://developers.cloudflare.com/workers/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/workers/</a> —— 边缘运行时(V8 isolate)与限制。</li><li>[2] Vercel.「Edge Functions.」<a href="https://vercel.com/docs/functions/edge-functions" target="_blank" rel="noreferrer">https://vercel.com/docs/functions/edge-functions</a> —— 边缘渲染平台与约束。</li><li>[3] web.dev / Next.js 文档.「Edge Runtime.」<a href="https://nextjs.org/docs/app/api-reference/edge" target="_blank" rel="noreferrer">https://nextjs.org/docs/app/api-reference/edge</a> —— 边缘运行时的 API 子集。</li></ul>`,23)])])}const h=r(n,[["render",a]]);export{u as __pageData,h as default};
